def check_B2(controller, reference_controllers, device, run_id):
 import sys,time,json,math,collections
 from pathlib import Path
 sys.path.insert(0,'results/T-048/scripts')
 from chay import OUT,read,dump,sha
 from kiem import read_run,doi_co_va_tang
 from cham import WORLDS
 folder=OUT/'runs'/run_id;folder.mkdir();start=time.monotonic();parent=OUT/'runs'/controller;command=read(parent/'command.json');allocation=read(OUT/'ma-tran.json')['allocation'];refs={};refhash={}
 for name in reference_controllers:
  for child in read(OUT/'runs'/name/'kiem.json')['finished']:
   cmd,meta,pairs=read_run(OUT/'runs'/child);refhash[child]=meta
   for j in cmd['plan']['jobs']:
    if allocation[j['opaque_id']]==device:refs[(j['opaque_id'],j['window'])]=child
 (folder/'command.json').write_text(dump(dict(controller=controller,references=reference_controllers,reference_hashes=refhash,analysis_source=ANALYSIS_SOURCE,no_labels=True,order='hash -> finite fields -> flags/validity/tiers -> N1/V0'))+'\n',encoding='utf-8')
 done=set();totals=collections.Counter();exceptions=[];deadline=start+10800
 with (folder/'trung-gian.jsonl').open('x',encoding='utf-8') as output,(folder/'progress.jsonl').open('x',encoding='utf-8') as progress:
  while len(done)<len(command['plan']['jobs']):
   if time.monotonic()>deadline:raise TimeoutError('B2 tới trần theo controller')
   for n,job in enumerate(command['plan']['jobs']):
    child=f'{controller}-{n:03d}';where=OUT/'runs'/child
    if child in done or not (where/'kiem.json').exists():continue
    _,meta,pairs=read_run(where);batch={r['config_id']:(r,d) for r,d in pairs()}
    refchild=refs[(job['opaque_id'],job['window'])];_,rmeta,rpairs=read_run(OUT/'runs'/refchild)
    r0,d0=next(rpairs());batch[r0['config_id']]=(r0,d0)
    result=dict(opaque_id=job['opaque_id'],window=job['window'],dataset=job['dataset'],child=child,reference_child=refchild,phase1=meta,reference_hashes=rmeta,bases={})
    for base,e4id in (('R0','R0-E4-S1-e0.05-a0.01'),('E1+E2','E1+E2-E4-S1')):
     er,ed=batch[e4id];row=dict(status=er['status'],variants={},z_distribution=[])
     # Full finite-domain check before reading the verdict/count summaries.
     for cid in (e4id,base+'-z-S1',base+'-z-S0'):
      r,d=batch[cid];t=d['trace'];invalid=[]; pv=0;oracle=0;fallback=0;maxz=None; key_count=0
      for unit,v in t['phan_vi'].items():
       if 'z' not in v:continue
       pv+=1;z=v['z'];fields=('med_N','IQR','c','z_len','z_xuong')
       if not all(isinstance(z.get(k),(int,float)) and math.isfinite(z[k]) for k in fields) or z['IQR']<0 or z['c']<=0:invalid.append(unit)
       else:
        oracle+=v.get('oracle',{}).get('z')=='finite_formula_match';fallback+=z['c']==1.0 and z['IQR']<10*sys.float_info.epsilon
        current=max(z['z_len'],z['z_xuong']);maxz=current if maxz is None else max(current,maxz)
        if cid==e4id:row['z_distribution'].append(dict(unit=unit,IQR=z['IQR'],c=z['c'],fallback=z['IQR']<10*sys.float_info.epsilon,z_len=z['z_len'],z_xuong=z['z_xuong'],A_extrema=v.get('A_extrema'),n_A=v['n_A'],n_N=v['n_N']))
       for direction in ('len','xuong'):
        score=v['e4']['e_'+direction];assert isinstance(score,(int,float)) and math.isfinite(score) and 0<=score<=1
      for rank in t['xep']:
       for block in rank['ket_qua']['blocks']:
        key_count+=1
        if not all(isinstance(x,(int,float)) and math.isfinite(x) for x in block['key']):invalid.append('ranking_key')
      check=doi_co_va_tang((er,ed['trace']),(r,t))
      assert t['normalized_input_sha256']==ed['trace']['normalized_input_sha256']
      row['variants'][cid]=dict(status=r['status'],PV_units=pv,oracle_finite=oracle,fallback_c1=fallback,max_z=maxz,invalid=invalid,gate_check=check,key_blocks=key_count)
      totals.update(records=1,PV_units=pv,invalid=len(invalid),gate_exceptions=not check['comparable'])
      if invalid or not check['comparable'] or r['status'] not in ('OK','NO_EVIDENCE'):exceptions.append(dict(child=child,config=cid,invalid=invalid,gate=check,status=r['status']))
     # N1/V0 only after the preceding native checks, including no-flag units.
     row['ce_interpretation']='không phân xử được do cấu tạo phép thử' if all(not v['invalid'] and v['gate_check']['comparable'] for v in row['variants'].values()) else 'Ngoại lệ B2: phần thuần đổi điểm chờ Minh'
     for cid in row['variants']:
      r,d=batch[cid];states=d['trace']['world_state'];row['variants'][cid]['worlds']={w:{k:states[w][k] for k in ('N1','V0','valid_units')} for w in WORLDS}
      if row['ce_interpretation'].startswith('không phân xử'):
       assert all({k:states[w][k] for k in ('N1','V0','valid_units')}=={k:ed['trace']['world_state'][w][k] for k in ('N1','V0','valid_units')} for w in WORLDS)
     result['bases'][base]=row
    output.write(dump(result)+'\n');output.flush();done.add(child)
    progress.write(dump(dict(child=child,completed=len(done),total=len(command['plan']['jobs']),elapsed=time.monotonic()-start))+'\n');progress.flush()
   if (parent/'kiem.json').exists():
    closed=read(parent/'kiem.json')
    if not closed['success']:raise RuntimeError('Nguồn T4b lỗi, giữ B2 đã kiểm')
   if len(done)<len(command['plan']['jobs']):time.sleep(10)
 (folder/'kiem.json').write_text(dump(dict(closed=True,jobs=len(done),totals=totals,exceptions=exceptions,trace_sha256=sha(folder/'trung-gian.jsonl'),wall_seconds=time.monotonic()-start))+'\n',encoding='utf-8')
 return dict(jobs=len(done),exceptions=len(exceptions))
